const {run} = require('/tmp/probe-degen/run.js');
const SEPS = '\t\n\x0b\x0c\r !"#$%&\'()*+,-./:;<=>?@[]^_`{|}~';
const NONSEP = 'abzABZ019\\\x7f —·éÉİẞΣ ​￿';
const ALPHA = (SEPS + SEPS + NONSEP).split('');
const SEPSET = new Set(SEPS.split(''));
function model(s){
  if (s === '') return '';
  const parts = [];
  let cur = '';
  for (const ch of s) {
    if (SEPSET.has(ch)) { if (cur) { parts.push(cur); cur=''; } }
    else cur += ch;
  }
  if (cur) parts.push(cur);
  const joined = parts.join('_');
  return (joined === '' ? '_' : joined).toLowerCase();
}
let fails=0, n=0, degen=0;
for (let i=0;i<600;i++){
  const len = Math.floor(Math.random()*14);
  let s='';
  for(let j=0;j<len;j++) s += ALPHA[Math.floor(Math.random()*ALPHA.length)];
  const r = run(s);
  const expHex = Buffer.from(model(s)+'\n','utf8').toString('hex');
  n++;
  if (model(s)==='_'||model(s)==='') degen++;
  if (r.out !== expHex) {
    fails++;
    if (fails<=12) console.log('MISMATCH in='+Buffer.from(s,'utf8').toString('hex')+' got='+r.out+' exp='+expHex);
  }
}
console.log(`cases=${n} degenerate=${degen} mismatches=${fails}`);
